-- @trak-suite mode=--staff-delivery-review in-all=true
-- Synthetic fixtures only. This suite also runs on native PostgreSQL.
BEGIN;
DO $$ BEGIN IF current_setting('trak.test_database',true) IS DISTINCT FROM 'disposable' THEN RAISE EXCEPTION 'Disposable database required'; END IF; END $$;
CREATE TEMP TABLE staff_results(label text PRIMARY KEY,passed boolean NOT NULL);
CREATE TEMP TABLE staff_tokens(label text PRIMARY KEY,payload jsonb NOT NULL);
GRANT ALL ON staff_results,staff_tokens TO authenticated,anon,service_role;
CREATE FUNCTION pg_temp.staff_assert(label text,passed boolean) RETURNS void LANGUAGE plpgsql AS $$
BEGIN INSERT INTO staff_results VALUES(label,coalesce(passed,false)); END $$;
CREATE FUNCTION pg_temp.staff_denied(label text,statement text,expected text DEFAULT '42501') RETURNS void LANGUAGE plpgsql AS $$
DECLARE denied boolean:=false; actual text;
BEGIN
  BEGIN
    EXECUTE statement;
    RAISE EXCEPTION 'Rollback unexpected success' USING ERRCODE='ZX001';
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS actual=RETURNED_SQLSTATE;
    IF actual=expected THEN denied:=true;
    ELSIF actual<>'ZX001' THEN RAISE; END IF;
  END;
  PERFORM pg_temp.staff_assert(label,denied);
END $$;
